mapper.select:
SELECT a.device_mete_id, f.cruise_time, f.cruise_type, h.dict_note as cruise_type_name, f.instance_name, g.task_type, i.dict_note AS c_type_name, f.result_num, f.identify_result, j.dict_note AS identify_result_name, f.cruise_result, z.dict_note as cruise_result_name, f.picpath as picPath, a.mete_type, m.dict_note as mete_type_name, a.meter_type, n.dict_note as meter_type_name FROM u_patrol_data_result f LEFT JOIN t_cruise_point_info w on w.instance_id = f.instance_id LEFT JOIN t_std_devicemete a on a.device_mete_id = w.device_mete_id LEFT JOIN u_patrol_task g ON f.task_id = g.task_id LEFT JOIN t_dict_business h ON f.cruise_type = h.dict_code AND h.col_name = "cruise_type" JOIN t_dict_business i ON g.task_type = i.dict_code AND i.col_name = "plan_type" LEFT JOIN t_dict_business j ON f.identify_result = j.dict_code AND j.col_name = "identify_result" LEFT JOIN t_dict_business z ON f.cruise_result=z.dict_code AND z.col_name="cruise_result" LEFT JOIN t_dict_business m ON m.dict_code = a.mete_type AND m.col_name="mete_type" LEFT JOIN t_dict_business n ON n.dict_code = a.meter_type AND n.col_name="meter_type" WHERE 1 = 1 and f.device_id IN
#{deviceIds,jdbcType=BIGINT}
and f.cruise_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP} and g.task_type = #{cType, jdbcType=INTEGER} and a.mete_type = #{meteType, jdbcType=VARCHAR} and a.meter_type = #{meterType, jdbcType=INTEGER} and f.instance_name LIKE CONCAT('%',#{instanceName, jdbcType=VARCHAR},'%') ORDER BY f.cruise_time DESC
